SELECT * FROM tblmi_comm_cd
WHERE GRP_ID = #{grp_id}

    and cd_id = #{cd_id}


    and cd_val = #{cd_val}

AND USE_YN = 'Y'
ORDER BY CD_SN

SELECT COUNT(*) FROM tblmi_kko_at_tmpl AS a
INNER JOIN tblmi_set_lst AS b
ON a.SEND_KEY = b.LIST_VAL
AND b.use_yn ='Y'


        and a.send_key = #{send_key}


        and a.tmpl_nm = #{tmpl_nm}


        and a.tmpl_nm like CONCAT('%', #{ex_tmpl_nm},'%')


        and a.chan_id = #{chan_id}


        and a.kep_status = #{kep_status}


        and a.use_yn = #{use_yn}


        and a.tmpl_status = #{tmpl_status}




                and a.reg_dt  >  #{reg_dt} and a.reg_dt  <  #{reg_dt_range}

            and a.reg_dt = #{reg_dt}




        and b.usr_grp_cd = #{usr_grp_cd}

SELECT a.seq AS seq, a.tmpl_cd AS tmpl_cd, a.send_key AS send_key, a.TMPL_NM AS tmpl_nm, a.tmpl_cont AS tmpl_cont, a.secur_flag AS secur_flag, a.tmpl_status AS tmpl_status, a.tmpl_msg_tp AS tmpl_msg_tp, a.tmpl_ext AS tmpl_ext, a.tmpl_ad AS tmpl_ad, a.tmpl_tit AS tmpl_tit, a.tmpl_subtit AS tmpl_subtit, a.tmpl_empsize_tp AS tmpl_empsize_tp, a.cate_cd AS cate_cd, a.tmpl_header AS tmpl_header, a.button_json AS button_json, a.quick_repl_json AS quick_repl_json, a.item_highlight_json AS item_heighlight_json, a.use_yn AS use_yn, a.etc_1 AS etc_1, a.etc_2 AS etc_2, a.etc_3 AS etc_3, a.etc_4 AS etc_4, a.etc_5 AS etc_5, a.etc_6 AS etc_6, a.etc_7 AS etc_7, a.etc_8 AS etc_8, a.etc_9 AS etc_9, a.etc_10 AS etc_10, a.reg_id AS reg_id, a.reg_dt AS reg_dt, a.upd_id AS upd_id, a.upd_dt AS upd_dt, CONCAT(b.list_nm ,'(',a.SEND_KEY,')') AS sender, c.img_nm, c.img_org_nm, c.img_url, c.kko_img_url FROM tblmi_kko_at_tmpl AS a INNER JOIN tblmi_set_lst AS b ON a.SEND_KEY = b.LIST_VAL AND b.use_yn ='Y' LEFT JOIN tblmi_cont_img AS c ON a.IMG_SEQ = c.SEQ
and a.send_key = #{send_key}
and a.tmpl_nm = #{tmpl_nm}
and a.tmpl_nm like CONCAT('%', #{ex_tmpl_nm},'%')
and a.chan_id = #{chan_id}
and a.kep_status = #{kep_status}
and a.use_yn = #{use_yn}
and a.tmpl_status = #{tmpl_status}
and a.reg_dt > #{reg_dt} and a.reg_dt < #{reg_dt_range}
and a.reg_dt = #{reg_dt}
and b.usr_grp_cd = #{usr_grp_cd}
order by a.REG_DT DESC
LIMIT #{firstIndex, javaType=int}, #{recordCountPerPage, javaType=int}

